INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5856073, 850386, 113055, '<td valign="top">I love the picture, but there is something about her rightside.  It looks like big moles/warts coming out of her.  It just looks weird..  But that could just be me...</td>', 'I love the picture, but there is something about her rightside.  It looks like big moles/warts coming out of her.  It just looks weird..  But that could just be me...', '2010-02-06 23:19:51.000000', NULL, 1),
(5856140, 851010, 106121, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2010-02-07 00:07:28.000000', NULL, 1),
(5856287, 850746, 62357, '<td valign="top">I love the concept here, but think the glow maybe just a little too much.</td>', 'I love the concept here, but think the glow maybe just a little too much.', '2010-02-07 02:31:20.000000', NULL, 1),
(5856622, 851236, 76335, '<td valign="top">Agh! The title... <br/> <br/>Cute shot anyway.</td>', 'Agh! The title...  Cute shot anyway.', '2010-02-07 11:04:34.000000', NULL, 1),
(5856682, 849946, 56828, '<td valign="top">I understand the concept and you are probably having other people tell you this. The challenge was to use the human body.  While this is a replication of a human, it''s not human.  Aside from DNMC, looking at the photo itself, you have some harsh  lights and shadows across the face that takes away from the photo.</td>', 'I understand the concept and you are probably having other people tell you this. The challenge was to use the human body.  While this is a replication of a human, it''s not human.  Aside from DNMC, looking at the photo itself, you have some harsh  lights and shadows across the face that takes away from the photo.', '2010-02-07 12:00:53.000000', NULL, 1),
(5856686, 850809, 56828, '<td valign="top">You are probably getting killed for this, but in my eyes, the challenge was to use parts of the HUMAN body.  While this is a replication of human, it''s not a human.  I think your lighting is great, the metal disc on the arm with the writing takes away from the photo.</td>', 'You are probably getting killed for this, but in my eyes, the challenge was to use parts of the HUMAN body.  While this is a replication of human, it''s not a human.  I think your lighting is great, the metal disc on the arm with the writing takes away from the photo.', '2010-02-07 12:02:45.000000', NULL, 1),
(5856687, 849733, 100393, '<td valign="top">This is a nice shot but I do think the vignette ruins your shot.</td>', 'This is a nice shot but I do think the vignette ruins your shot.', '2010-02-07 12:03:36.000000', NULL, 1),
(5856688, 851220, 56828, '<td valign="top">I''m assuming you meant for it to look like an old shool polaroid.  I think it''s too blurry and has entirely too much noise.  your mixed lighting (the lamp and the window, don''t blend well either.</td>', 'I''m assuming you meant for it to look like an old shool polaroid.  I think it''s too blurry and has entirely too much noise.  your mixed lighting (the lamp and the window, don''t blend well either.', '2010-02-07 12:03:58.000000', NULL, 1),
(5856690, 850921, 56828, '<td valign="top">You have a decent landscape shot and great capture of the birds.  The body part actually distracts from the whole photo.   It almost loooks like the hand was in there on accident.</td>', 'You have a decent landscape shot and great capture of the birds.  The body part actually distracts from the whole photo.   It almost loooks like the hand was in there on accident.', '2010-02-07 12:05:29.000000', NULL, 1),
